<template>
  <div class="grid w-full max-w-sm items-center gap-1.5">
    <Label :for="label">{{ label }}</Label>
    <DatePicker
      v-if="datePicker"
      :id="label"
      v-model:open="isOpen"
      :model-value="internalDateValue"
      button-class="col-span-full border-border"
      :max-value="today(getLocalTimeZone())"
      :min-value="new CalendarDate(1900, 1, 1)"
      @update:model-value="(val) => handleInputChange(true, val)"
    />
    <Input
      v-else
      :id="label"
      v-model="internalValue"
      v-maska="maska || basicInputMask"
      type="input"
      class="border-border"
      :data-maska="maska"
      @input="() => handleInputChange(false)"
    />
  </div>
</template>

<script setup lang="ts">
import { CalendarDate, parseDate, today, getLocalTimeZone } from '@internationalized/date';
interface Props {
  label: string;
  modelValue: string | null;
  maska?: string;
  datePicker?: boolean;
}

const props = defineProps<Props>();
const emit = defineEmits(['update:modelValue']);

const internalValue = ref<string | null | undefined>(props.modelValue || '');
const internalDateValue = ref<null | undefined | CalendarDate>(
  props.modelValue && props.datePicker ? parseDate(props.modelValue) : undefined
);

let isUserModified = false;
const isOpen = ref<boolean>(false);

watch(
  () => props.modelValue,
  (newValue) => {
    if (!isUserModified && newValue) {
      if (props.datePicker) internalDateValue.value = parseDate(newValue);
      else internalValue.value = newValue;
    }
  }
);

function handleInputChange(isClose: boolean, dateValue?: CalendarDate) {
  isUserModified = true;
  emit('update:modelValue', props.datePicker ? dateValue?.toString() || '' : internalValue.value);
  if (props.datePicker) internalDateValue.value = dateValue;
  if (isClose && isOpen.value) isOpen.value = false;
}

const basicInputMask = {
  preProcess: (val: string) => {
    return Array.from(val)
      .filter((ch) => {
        if (/[A-Za-z]/.test(ch)) return true;

        if (/\p{L}/u.test(ch)) return false;

        return true;
      })
      .join('');
  },
};
</script>

<style scoped lang="scss"></style>
